'use server'

import { supabase } from '@/lib/supabase'

export interface Certificate {
  id: string
  name: string
  school: string
  certificate_type: string
  committee: string
  country: string
  created_at: string
}

export async function searchCertificate(query: string): Promise<{ success: boolean; data?: Certificate[]; error?: string }> {
  if (!query) {
    return { success: false, error: 'Please enter a certificate ID or name' }
  }

  try {
    // Try to search by ID first (exact match)
    const { data: idData } = await supabase
      .from('certificates')
      .select('*')
      .eq('id', query)
      .single()

    if (idData) {
      return { success: true, data: [idData] }
    }

    // If not found by ID, search by name (case-insensitive partial match)
    const { data: nameData, error: nameError } = await supabase
      .from('certificates')
      .select('*')
      .ilike('name', `%${query}%`)
      .limit(10)

    if (nameError) {
      console.error('Supabase search error:', nameError)
      return { success: false, error: 'Failed to search certificates' }
    }

    if (!nameData || nameData.length === 0) {
      return { success: false, error: 'No certificates found' }
    }

    return { success: true, data: nameData }
  } catch (error) {
    console.error('Search error:', error)
    return { success: false, error: 'An unexpected error occurred' }
  }
}
